import{_ as a,o as n,c as e,ag as p}from"./chunks/framework.DUTPmUpA.js";const i="/_assets/npm-run-dev-cmd.DNxnfQMp.png",m=JSON.parse('{"title":"Генератор подсказок","description":"","frontmatter":{"title":"Генератор подсказок","author":"Shush, AKA the Typescript prophet","steamId":76561197994333650,"date":"18.01.2021"},"headers":[],"relativePath":"scripting/Typescript/tooltip-generator.md","filePath":"scripting/Typescript/tooltip-generator.md"}'),l={name:"scripting/Typescript/tooltip-generator.md"};function o(t,s,r,c,d,u){return n(),e("div",null,[...s[0]||(s[0]=[p(`<p>Генератор подсказок</p><p>Недавно завершилась разработка нового проекта под названием Tooltip Generator. Этот проект был вдохновлен идеей Ark Eaglesong, целью которой было максимально упростить добавление локализации, одновременно уменьшив вероятность совершения ошибок. Этот проект включает в себя второстепенную часть, совершенно необязательную, под названием Tooltip Codemaker, которая помогает тем, у кого уже есть рабочий аддон с большим количеством локализации.</p><h2 id="генератор-подсказок" tabindex="-1">Генератор подсказок <a class="header-anchor" href="#генератор-подсказок" aria-label="Permalink to &quot;Генератор подсказок&quot;">​</a></h2><p>Генератор подсказок создает предопределенные объекты Typescript, которые относятся к одной из трех категорий: стандартные подсказки, способности и модификаторы. Преимуществом этого является возможность написать очень простой для чтения объект с помощью кода на основе создаваемой вами группы всплывающих подсказок. Всякий раз, когда вы вносите изменения в любой из файлов и сохраняете их, генератор подсказок немедленно возьмет созданный вами код и создаст файлы локализации (например, addon_english.txt), которые игра сможет прочитать. Это можно расширить для поддержки бесконечного множества языков, а также использовать тот же код с небольшими изменениями в полях, которые вы хотите изменить.</p><h2 id="подожди-машинопись-моя-установка-—-lua" tabindex="-1">Подожди, Машинопись? Моя установка — lua! <a class="header-anchor" href="#подожди-машинопись-моя-установка-—-lua" aria-label="Permalink to &quot;Подожди, Машинопись? Моя установка — lua!&quot;">​</a></h2><p>Этот проект предназначен для работы как с надстройками на основе Lua, так и с Typescript. Хотя для локализации вам придется использовать Typescript специально, на остальную часть вашего аддона это совершенно не повлияет.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Most editors have plugins that add Typescript support. VSCode has built-in Typescript support and requires no plugins. In order to view Typescript syntax, make sure that your editor has Typescript support installed or enabled.</p></div><h2 id="why-would-i-ever-bother-using-that-though" tabindex="-1">Why would I ever bother using that though? <a class="header-anchor" href="#why-would-i-ever-bother-using-that-though" aria-label="Permalink to &quot;Why would I ever bother using that though?&quot;">​</a></h2><p>There are a few reasons why I&#39;ve started this project in the first place. I was getting frustrated by the &quot;rules&quot; of the KV, such as having to copy &quot;DOTA_Tooltip_Ability_my_ability_name&quot; over and over. I constantly mistyped &quot;Description&quot;, and occasionally used only 2 percentages instead of 3 on &quot;%something%%%&quot; to show a variable with a percentage. And if I ever had a missing quote, the entire thing got broken, which is extremely annoying.</p><p>In addition, as I&#39;ve developed my game, my addon file became <strong>HUGE</strong>. Because of the way Dota reads this file, you cannot use #base to split this into files, and some people have resorted to making a manual script that does that. It&#39;s a lot of hassle and wasted time for everyone involved.</p><p>This project attempts to solve all those problems:</p><ul><li>Это гарантирует, что вы никогда не допустите ошибок форматирования.</li><li>Вы создаете только один объект для каждой способности или модификатора и заполняете для него все детали. — Вы можете использовать предопределенные перечисления для правильного вызова свойств модификатора.</li><li>Вы можете разделить его на любое количество файлов.</li><li>Вы можете легко использовать свои собственные переменные для использования повторяющихся ключевых слов.</li><li>Все языки хранятся в одном месте и правильно распределяются по соответствующим файлам.</li></ul><p>Я советую вам хотя бы попробовать этот проект. Вы не будете разочарованы.</p><h2 id="что-мне-нужно-чтобы-использовать-его" tabindex="-1">Что мне нужно, чтобы использовать его? <a class="header-anchor" href="#что-мне-нужно-чтобы-использовать-его" aria-label="Permalink to &quot;Что мне нужно, чтобы использовать его?&quot;">​</a></h2><p>Для работы этого проекта используются пакеты Typescript и npm. Оба из них требуют <a href="https://nodejs.org/en/" target="_blank" rel="noreferrer">NodeJS</a>. Если он у вас не установлен или у вас очень старая версия, загрузите последнюю стабильную версию с сайта NodeJS и установите ее.</p><h2 id="создатель-кода-подсказок" tabindex="-1">Создатель кода подсказок <a class="header-anchor" href="#создатель-кода-подсказок" aria-label="Permalink to &quot;Создатель кода подсказок&quot;">​</a></h2><p>Когда я разрабатывал генератор подсказок, я вручную выполнял каждую локализацию, которую мне приходилось писать, и когда я закончил, я подумал про себя: почему бы мне просто не написать сценарий, который сделает это за меня?</p><p>Это привело к появлению Tooltip Codemaker. Tooltip Codemaker является полной противоположностью Tooltip Generator: вместо того, чтобы превращать код в KV локализации, он превращает KV локализации в код! Это особенно полезно, если у вас уже есть много работ по локализации, выполненных KV.</p><p>В большинстве случаев вы будете использовать этот инструмент не более одного раза, чтобы превратить текущий KV в код. Предполагается, что после этого вы продолжите создавать остальные всплывающие подсказки с помощью генератора подсказок. Если ваш аддон совершенно пустой, то он вам вообще не нужен.</p><p>Обратите внимание, что Codemaker не является и не может быть идеальным из-за особенностей определения KV локализации. Он ищет такие ключевые слова, как <code>_Description</code>, <code>_Lore</code>, <code>_Note</code> и т. д., чтобы точно определить фактическое имя способности, а затем группирует все похожие KV для этой способности. Способности, имеющие очень похожую схему наименования, могут быть ошибочно сгруппированы вместе; например, в ванильной Dota способности <code>ice_blast</code> и <code>ice_blast_release</code> были сгруппированы в одну, поскольку считалось, что <code>_release</code> является одной из специальных способностей <code>ice_blast</code>. Просто обязательно просмотрите код после запуска скрипта и исправьте ошибки вручную, если таковые имеются. Скрипт предполагает, что все, что начинается с <code>Dota_Tooltip_Ability_...</code>, является способностью, а все, что начинается с <code>Dota_Tooltip_modifier_...</code>, является модификатором (без учета регистра). Все остальное рассматривается как стандартная подсказка. Это означает, что в зависимости от ваших KV вам, возможно, придется внести изменения в компилятор перед его запуском, чтобы он работал с файлами локализации вашего дополнения.</p><p>Вы можете найти Tooltip Codemaker в <a href="https://github.com/Shushishtok/tooltip-codemaker" target="_blank" rel="noreferrer">this github repo</a>. Следуйте инструкциям по его использованию.</p><h2 id="установка-генератора-подсказок" tabindex="-1">Установка генератора подсказок <a class="header-anchor" href="#установка-генератора-подсказок" aria-label="Permalink to &quot;Установка генератора подсказок&quot;">​</a></h2><p>Чтобы использовать генератор подсказок, вам необходимо его установить. Это необходимо сделать только один раз для каждого проекта. Перейдите в корень игры вашего аддона. Для большинства проектов это будет <code>dota 2 beta/game/dota_addons/your_addon/</code>. Если вы используете символические ссылки или конфигурацию Typescript, папка с символической ссылкой, скорее всего, будет корнем вашей папки.</p><p>Нажмите на строку пути к папке, введите <code>cmd</code> и нажмите Enter. Это должно открыть командную строку для папки, в которой вы сейчас находитесь. Если вы не уверены, где находится строка пути, нажмите Alt+D, чтобы выделить ее.</p><p>В командной строке введите <code>npm install @shushishtok/tooltip_generator</code>. Установка должна занять несколько секунд, что приведет к запуску дополнительной, «окончательной» установки, которая может занять до нескольких минут. По завершении установки должно появиться сообщение об успехе и несколько предупреждений — вы можете игнорировать эти предупреждения. Оставьте командную строку открытой. После завершения установки в корень вашего дополнения добавляется новый файл <code>package.json</code> вместе с папкой <code>node_modules</code>. В большинстве случаев вы можете полностью игнорировать эти файлы.</p><p>При установке предполагается, что ваша папка <code>resource</code> расположена в корне вашего компьютера, как и должно быть в случае со стандартными аддонами, созданными Dota Workshop. Если да, пропускайте дальше. Однако если это не так, откройте <code>package.json</code> и измените поле <code>&quot;~resource&quot;: &quot;resource&quot;,</code>, чтобы оно соответствовало пути от корневой папки к этой папке. Например, в конфигурациях Typescript с использованием шаблона Typescript Moddota его необходимо будет изменить на <code>&quot;~resource&quot;: &quot;game/resource&quot;,</code>. Сохраните файл и закройте его.</p><p>В командной строке введите <code>npm run init</code> и нажмите Enter. Это добавило несколько файлов в вашу папку <code>resource</code>, которые вы также можете игнорировать. Вы также увидите новую папку <code>localization</code>, которая является ядром всех ваших файлов локализации с кодом Typescript.</p><p>:::опасность Следующий шаг активирует генератор подсказок, который полностью удалит все файлы локализации вашего дополнения (например, <code>addon_english.txt</code>) и заменит их вашим кодом. Обязательно сделайте резервную копию, прежде чем продолжить! :::</p><h2 id="тестирование-генератора-подсказок" tabindex="-1">Тестирование генератора подсказок <a class="header-anchor" href="#тестирование-генератора-подсказок" aria-label="Permalink to &quot;Тестирование генератора подсказок&quot;">​</a></h2><p>Перейдите в папку <code>localization</code> внутри папки <code>resource</code>. В этой папке вы найдете <code>localizationData.ts</code>. Это используется в качестве образца для генератора подсказок. Откройте его и найдите следующий код:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts</span></span>
<span class="line"><span>StandardTooltips.push({</span></span>
<span class="line"><span>  classname: &#39;Hello&#39;,</span></span>
<span class="line"><span>  name: &#39;test&#39;,</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Этот объект представляет собой стандартную всплывающую подсказку, которая, как ожидается, будет преобразована в <code>&quot;Hello&quot; &quot;test&quot;</code> в KV. Давайте проверим его, чтобы проверить, работает ли он так, как ожидалось.</p><p>Используя ту же командную строку, что и раньше, запустите <code>npm run dev</code>. Если он работает так, как ожидалось, вы должны увидеть, что он просматривает несколько файлов и написал несколько локализаций: <img src="`+i+`" alt="npm run dev"></p><p>Проверьте файл <code>addon_english.txt</code>. Теперь у него должна быть только одна локализация, поскольку у нас есть только один тестовый объект.</p><p>:::информация Пока в командной строке выполняется команда <code>npm run dev</code>, процесс-наблюдатель работает и ожидает изменений. Любые изменения, внесенные в файлы в папке <code>localization</code>, немедленно перекомпилируют файлы и заново создадут файлы <code>addon_&lt;language&gt;</code>. ::: Вы можете заметить, что существуют и другие языковые файлы. По умолчанию включены английский, русский и стандартный китайский (SCchinese). Позже в этом руководстве мы обсудим управление языком для этих файлов. На данный момент все файлы имеют одинаковый вывод, поэтому вы можете пока их игнорировать.</p><p>Чтобы убедиться, что наблюдатель работает правильно, вернитесь к <code>localizationData.ts</code> и создайте новый объект стандартной всплывающей подсказки следующим образом:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts</span></span>
<span class="line"><span>StandardTooltips.push({</span></span>
<span class="line"><span>  classname: &#39;watcher_test&#39;,</span></span>
<span class="line"><span>  name: &#39;This should be automatically added&#39;,</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Сохраните файл. Ваша командная строка обновилась (не волнуйтесь, если вы ее пропустили). Проверьте свой <code>addon_english.txt</code> (возможно, вам придется закрыть его и открыть снова, чтобы увидеть изменения). Если теперь вы видите и вторую локализацию <code>&quot;watcher_test&quot; &quot;This should be automatically added&quot;</code>, тест пройден успешно.</p><p>:::информация Вы можете активировать наблюдатель в любом редакторе, поддерживающем сборки npm, например VSCode, запустив в нем <code>npm run dev</code>. Sublime также имеет такую ​​поддержку, но требует короткой настройки, которую вы можете найти в файле readme <a href="https://github.com/Shushishtok/tooltip_generator" target="_blank" rel="noreferrer">Tooltip Generator Github repo</a>. В любом случае, вы всегда можете использовать для этого командную строку. Обратной стороной этого является необходимость открытия окна командной строки во время работы наблюдателя, что не так весело. :::</p><h2 id="типы-локализации" tabindex="-1">Типы локализации <a class="header-anchor" href="#типы-локализации" aria-label="Permalink to &quot;Типы локализации&quot;">​</a></h2><p>В базовой форме генератора локализаций каждая локализация относится к одной из трех категорий:</p><ul><li><p>Стандартные подсказки: все, что не является способностью или модификатором. Не имеет предопределенной структуры ключей и может быть чем угодно. Приведенные выше примеры представляют собой стандартные всплывающие подсказки. Это самые простые типы КВ.</p></li><li><p>Подсказки к способностям: все способности соответствуют ключевой структуре <code>DOTA_Tooltip_ability_abilityname</code>. У них также есть предопределенные ключи-суффиксы, такие как <code>_Description</code>, <code>_Lore</code>, <code>_Note0</code> и т. д. Один объект всплывающей подсказки способности может включать в себя множество свойств, как упоминалось выше, и поддерживает все ключи-суффиксы способностей.</p></li><li><p>Подсказки модификаторов: все модификаторы соответствуют ключевой структуре <code>DOTA_Tooltip_modifiername</code>. Обычно имя каждого модификатора начинается с <code>modifier_...</code>, но здесь это должно работать, даже если вы назвали свои модификаторы по-другому.</p></li></ul><p>В моем личном моде Dota Reimagined я создал еще два типа локализации подсказок: Reimagined Tooltips и Talent Tooltips. Они отключены (закомментированы) в компиляторе, потому что не работают в стандартных режимах (даже в талантах, в моем моде эта система сделана специально). Однако их можно использовать как хороший справочник для настройки дополнительных типов локализации, если вы того пожелаете. Не стесняйтесь проверить компилятор (находится по адресу <code>node_modules/@shushishtok/tooltip_generator/localizationCompiler.ts</code>) и настроить его по своему усмотрению. Вышеупомянутых типов подсказок должно быть достаточно для большинства режимов.</p><h2 id="пример-стандартнои-подсказки" tabindex="-1">Пример стандартной подсказки <a class="header-anchor" href="#пример-стандартнои-подсказки" aria-label="Permalink to &quot;Пример стандартной подсказки&quot;">​</a></h2><p>Стандартные всплывающие подсказки чрезвычайно просты и их очень легко создать. Они имеют следующие поля:</p><ul><li>Имя класса: строка</li><li>Имя: строка</li></ul><p>Имя класса — это левая часть ключевого слова, а имя — справа. Например, следующий объект всплывающей подсказки:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts</span></span>
<span class="line"><span>StandardTooltips.push({</span></span>
<span class="line"><span>  classname: &#39;standard_tooltip_example&#39;,</span></span>
<span class="line"><span>  name: &#39;Tooltip Example&#39;,</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Изготовлю следующие КВ:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>txt</span></span>
<span class="line"><span>&quot;standard_tooltip_example&quot;      &quot;Tooltip Example&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Как видите, он создает именно связь имени класса объекта, без применения какой-либо другой логики.</p><h2 id="пример-локализации-способностеи" tabindex="-1">Пример локализации способностей <a class="header-anchor" href="#пример-локализации-способностеи" aria-label="Permalink to &quot;Пример локализации способностей&quot;">​</a></h2><p>Подсказки способностей, вероятно, содержат самые большие объекты, поскольку способности могут включать в себя множество свойств. Каждое свойство имеет ожидаемый тип (поясняется позже). Подсказки способностей имеют следующие поля:</p><ul><li>Имя класса способности: строка</li><li>Имя: строка</li><li>Описание: строка</li><li>История: строка</li><li>Примечания: Массив строк.</li><li>Описание скипетра: строка</li><li>Описание осколка: строка</li><li>Специальные способности: массив специальных объектов способностей.</li></ul><p>Вы можете заметить, что примечания и специальные способности представляют собой массивы. Это связано с тем, что способность может (технически) иметь неопределенное количество примечаний и специальных способностей, которые определены здесь. Начнем с простого примера способностей:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts</span></span>
<span class="line"><span>Abilities.push({</span></span>
<span class="line"><span>  ability_classname: &#39;aghanims_shard_explosion&#39;,</span></span>
<span class="line"><span>  name: &#39;Shard Explosion&#39;,</span></span>
<span class="line"><span>  description: &#39;Fires a shard at the target point which deals damage on impact.&#39;,</span></span>
<span class="line"><span>  lore: &quot;Aghanims&#39; signature move, firing shards of arcane energy.&quot;,</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Это просто и создаст следующую способность KV:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>txt</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion&quot;    &quot;Shard Explosion&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_description&quot;    &quot;Fires a shard at the target point which deals damage on impact.&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_Lore&quot;    &quot;Aghanims&#39; signature move, firing shards of arcane energy.&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Довольно изящно, правда? Добавим к способности эффекты скипетра и осколков:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts</span></span>
<span class="line"><span>Abilities.push({</span></span>
<span class="line"><span>  ability_classname: &#39;aghanims_shard_explosion&#39;,</span></span>
<span class="line"><span>  name: &#39;Shard Explosion&#39;,</span></span>
<span class="line"><span>  description: &#39;Fires a shard at the target point which deals damage to all enemies on impact.&#39;,</span></span>
<span class="line"><span>  lore: &quot;Aghanims&#39; signature move, firing shards of arcane energy.&quot;,</span></span>
<span class="line"><span>  scepter_description: &#39;Increases damage and explosion range.&#39;,</span></span>
<span class="line"><span>  shard_description: &#39;Decreases cooldown of the ability.&#39;,</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>После сохранения в локализацию сразу добавляются:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>txt</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion&quot;    &quot;Shard Explosion&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_description&quot;    &quot;Fires a shard at the target point which deals damage to all enemies on impact.&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_Lore&quot;    &quot;Aghanims&#39; signature move, firing shards of arcane energy.&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_scepter_description&quot;    &quot;Increases damage and explosion range.&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_shard_description&quot;    &quot;Decreases cooldown of the ability.&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Возможно, вы заметили, что я не использовал для этой способности никаких чисел или специальных переменных, поэтому давайте обсудим это. Большинство полей способностей поддерживают использование переменных, которые можно заменять в игре числами в зависимости от значения специальной способности. В KV это обычно делается в формате <code>%something%</code>, где <code>something</code> отражает особое значение способности. Использование процентов в качестве разделителя всегда казалось мне ошибочным. Вместо этого мы используем разделитель <code>{something}</code>. Переменные, определенные таким образом, будут правильно обработаны в формате, ожидаемом KV. Преимуществом этого является добавление к процентам: если вы хотите отобразить <code>20%</code> в игре, где <code>20</code> — ваша особая способность, все, что вам нужно сделать, это <code>{something}%</code>. Давайте приведем пример этого в наших возможностях:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts</span></span>
<span class="line"><span>Abilities.push({</span></span>
<span class="line"><span>  ability_classname: &#39;aghanims_shard_explosion&#39;,</span></span>
<span class="line"><span>  name: &#39;Shard Explosion&#39;,</span></span>
<span class="line"><span>  description:</span></span>
<span class="line"><span>    &#39;Fires a shard at the target point which deals {damage} damage to all enemies on impact.&#39;,</span></span>
<span class="line"><span>  lore: &quot;Aghanims&#39; signature move, firing shards of arcane energy.&quot;,</span></span>
<span class="line"><span>  scepter_description:</span></span>
<span class="line"><span>    &#39;Increases damage by {scepter_damage} and explosion range by {scepter_aoe_bonus}.&#39;,</span></span>
<span class="line"><span>  shard_description: &#39;Decreases cooldown of the ability by {shard_cd_pct}%.&#39;,</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>Это переводится в правильный KV:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>txt</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion&quot;    &quot;Shard Explosion&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_description&quot;    &quot;Fires a shard at the target point which deals %damage% damage to all enemies on impact.&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_Lore&quot;    &quot;Aghanims&#39; signature move, firing shards of arcane energy.&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_scepter_description&quot;    &quot;Increases damage by %scepter_damage% and explosion range by %scepter_aoe_bonus%.&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_shard_description&quot;    &quot;Decreases cooldown of the ability by %shard_cd_pct%%%.&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Наконец, давайте поговорим о заметках и специальных способностях. Примечания представляют собой массивы строк, каждая из которых отражает примечание о способности. Компилятор правильно скомпилирует их в Note0, Note1, Note2 и т. д., которые ожидает игра.</p><p>Специальные способности немного сложнее. Это массивы специальных объектов способностей. Каждый объект ожидает, по крайней мере, специального имени способности и ее внутриигрового текста, например «shard_damage» и «DAMAGE». Он не ожидает ничего, кроме текста. Однако он поддерживает два необязательных поля:</p><ul><li>Процент</li><li>Статистика предмета</li></ul><p>Оба этих значения являются логическими значениями, которые по умолчанию имеют значение false, если они опущены, и могут быть включены только в том случае, если вы хотите их специально включить. Поле процентов добавляет <code>%</code> в начало текста, а статистика элемента вместо этого добавляет \`+Наконец, давайте поговорим о заметках и специальных способностях. Примечания представляют собой массивы строк, каждая из которых отражает примечание о способности. Компилятор правильно скомпилирует их в Note0, Note1, Note2 и т. д., которые ожидает игра.</p><p>Специальные способности немного сложнее. Это массивы специальных объектов способностей. Каждый объект ожидает, по крайней мере, специального имени способности и ее внутриигрового текста, например «shard_damage» и «DAMAGE». Он не ожидает ничего, кроме текста. Однако он поддерживает два необязательных поля:</p><ul><li>Процент</li><li>Статистика предмета</li></ul><p>Оба этих значения являются логическими значениями, которые по умолчанию имеют значение false, если они опущены, и могут быть включены только в том случае, если вы хотите их специально включить. Поле процентов добавляет <code>%</code> в начало текста, а статистика элемента вместо этого добавляет . Давайте создадим полную подсказку для способностей, интегрировав ее в наш пример выше:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts</span></span>
<span class="line"><span>Abilities.push({</span></span>
<span class="line"><span>  ability_classname: &#39;aghanims_shard_explosion&#39;,</span></span>
<span class="line"><span>  name: &#39;Shard Explosion&#39;,</span></span>
<span class="line"><span>  description:</span></span>
<span class="line"><span>    &#39;Fires a shard at the target point which deals {damage} damage to all enemies on impact.&#39;,</span></span>
<span class="line"><span>  lore: &quot;Aghanims&#39; signature move, firing shards of arcane energy.&quot;,</span></span>
<span class="line"><span>  scepter_description:</span></span>
<span class="line"><span>    &#39;Increases damage by {scepter_damage} and explosion range by {scepter_aoe_bonus}.&#39;,</span></span>
<span class="line"><span>  shard_description: &#39;Decreases cooldown of the ability by {shard_cd_pct}%.&#39;,</span></span>
<span class="line"><span>  notes: [</span></span>
<span class="line"><span>    &#39;The projectile moves at {projectile_speed} speed.&#39;,</span></span>
<span class="line"><span>    &#39;Despite the visual effect, all enemies in range immediately take damage upon impact.&#39;,</span></span>
<span class="line"><span>    &#39;Can be disjointed.&#39;,</span></span>
<span class="line"><span>  ],</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ability_specials: [</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>      ability_special: &#39;damage&#39;,</span></span>
<span class="line"><span>      text: &#39;DAMAGE&#39;,</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>      ability_special: &#39;radius&#39;,</span></span>
<span class="line"><span>      text: &#39;EXPLOSION RADIUS&#39;,</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>      ability_special: &#39;scepter_cd_reduction&#39;,</span></span>
<span class="line"><span>      text: &#39;COOLDOWN REDUCTION&#39;,</span></span>
<span class="line"><span>      percentage: true,</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>  ],</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br></div></div><p>Объект «Подсказка способностей» выглядит больше из-за пробелов между каждым специальным объектом способности, но, честно говоря, это мое собственное предпочтение в кодировании — пока вы придерживаетесь структуры объектов внутри массива, он все равно будет обрабатывать информацию так же хорошо.</p><p>Это обрабатывается до финального KV, который игра прекрасно читает:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>txt</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion&quot;    &quot;Shard Explosion&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_description&quot;    &quot;Fires a shard at the target point which deals %damage% damage to all enemies on impact.&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_Lore&quot;    &quot;Aghanims&#39; signature move, firing shards of arcane energy.&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_Note0&quot;    &quot;The projectile moves at %projectile_speed% speed.&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_Note1&quot;    &quot;Despite the visual effect, all enemies in range immediately take damage upon impact.&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_Note2&quot;    &quot;Can be disjointed.&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_scepter_description&quot;    &quot;Increases damage by %scepter_damage% and explosion range by %scepter_aoe_bonus%.&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_shard_description&quot;    &quot;Decreases cooldown of the ability by %shard_cd_pct%%%.&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_damage&quot;    &quot;DAMAGE&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_radius&quot;    &quot;EXPLOSION RADIUS&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_Ability_aghanims_shard_explosion_scepter_cd_reduction&quot;    &quot;%COOLDOWN REDUCTION&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h2 id="пример-локализации-модификатора" tabindex="-1">Пример локализации модификатора <a class="header-anchor" href="#пример-локализации-модификатора" aria-label="Permalink to &quot;Пример локализации модификатора&quot;">​</a></h2><p>Последняя группа — это подсказка модификатора. В отличие от способностей, модификаторы имеют только имя класса, имя и описание. Однако у них также есть собственный элемент: они могут представлять динамические значения, используя свойства-модификаторы. Я всегда использовал их неправильно, поэтому предпринял дополнительный шаг, чтобы это исправить. А пока давайте создадим простой модификатор:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts</span></span>
<span class="line"><span>Modifiers.push({</span></span>
<span class="line"><span>  modifier_classname: &#39;modifier_greater_power&#39;,</span></span>
<span class="line"><span>  name: &#39;Greater Power&#39;,</span></span>
<span class="line"><span>  description: &#39;Increases your base damage and your move speed.&#39;,</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Он очень быстро перерабатывается в следующий KV:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>txt</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_modifier_greater_power&quot;    &quot;Greater Power&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_modifier_greater_power_description&quot;    &quot;Increases your base damage and your move speed.&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>На этот раз мы хотим также включить точный бонус к базовому урону и бонус к скорости передвижения, которые вы получаете от этого модификатора. Предполагая, что вы увеличиваете базовый урон с помощью свойства-модификатора <code>MODIFIER_PROPERTY_PREATTACK_BONUS_DAMAGE</code>, мы можем использовать перечисление для его использования. Обратите внимание: чтобы иметь возможность вставлять переменные в строки, нам нужно использовать интерполяцию строк, которая осуществляется путем заключения строки в обратные кавычки (если это неясно, см. пример). Кроме того, мы должны придерживаться следующей структуры: <code>{\${LocalizationModifierProperty.SOME_PROPERTY}}</code>. При использовании строковой интерполяции <code>\${variable}</code> преобразуется во время компиляции в фактическое значение переменной. Это позволяет нам использовать перечисления для этих свойств модификаторов.</p><p>:::информация При вызове перечислений вам нужно указать только имя свойства, а не всю строку. Например, <code>MODIFIER_PROPERTY_PREATTACK_BONUS_DAMAGE</code> можно вызвать, просто набрав <code>PREATTACK_BONUS_DAMAGE</code>. Компилятор по-прежнему будет правильно обрабатывать его в той форме, которую ожидает игра. :::</p><p>Давайте улучшим приведенный выше пример с помощью динамических переменных. Бонус к скорости передвижения представляет собой процентный бонус, поэтому мы также добавим к нему знак <code>%</code>.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts</span></span>
<span class="line"><span>Modifiers.push({</span></span>
<span class="line"><span>  modifier_classname: &#39;modifier_greater_power&#39;,</span></span>
<span class="line"><span>  name: &#39;Greater Power&#39;,</span></span>
<span class="line"><span>  description: \`Increases your base damage by {\${LocalizationModifierProperty.PREATTACK_BONUS_DAMAGE}} and your move speed by {\${LocalizationModifierProperty.MOVESPEED_BONUS_PERCENTAGE}}%.\`,</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Эти значения являются перечислениями, поэтому компилятор следит за тем, чтобы они были введены правильно, и, если они окружены <code>{}</code>, они должны быть правильно обработаны. Это преобразуется в KV следующим образом:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>txt</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_modifier_greater_power&quot;    &quot;Greater Power&quot;</span></span>
<span class="line"><span>&quot;DOTA_Tooltip_modifier_greater_power_description&quot;    &quot;Increases your base damage by %dMODIFIER_PROPERTY_PREATTACK_BONUS_DAMAGE% and your move speed by %dMODIFIER_PROPERTY_MOVESPEED_BONUS_PERCENTAGE%%%.&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Это работает для всех свойств модификатора.</p><p>:::информация Свойство принимает префикс <code>d</code> (целое число). Если вы хотите вместо этого использовать префикс <code>f</code> (с плавающей запятой), вы можете вызвать его с помощью <code>{f\${LocalizationModifierProperty.PREATTACK_BONUS_DAMAGE}}</code>. На данный момент <code>f</code> является единственным дополнительным поддерживаемым ключевым словом. :::</p><h2 id="языковои-контроль" tabindex="-1">Языковой контроль <a class="header-anchor" href="#языковои-контроль" aria-label="Permalink to &quot;Языковой контроль&quot;">​</a></h2><p>Каждая подсказка может иметь разные значения в зависимости от языка клиента, поэтому у нас есть много файлов <code>addon_&lt;language&gt;.txt</code>, по одному для каждого языка. Разные моды имеют разную языковую поддержку в зависимости от основного языка режима и дополнительных переводов. Это привело к необходимости языкового контроля. В верхней части файла .TS вы можете увидеть импорт для <code>Language</code>. Это перечисление определяет, какие языки включены; каждый включенный язык создаст свой файл <code>addon_&lt;language&gt;.txt</code>. По умолчанию включены английский, русский и стандартный китайский языки. Кроме того, также включен «язык» <code>None</code> — он используется только для компиляции и не должен отключаться или использоваться.</p><p>Чтобы включить или отключить язык, перейдите к <code>/game/resource/languages.ts</code>. Внутри него вы должны увидеть <code>export enum Language</code>, в котором есть список языков. Просто прокомментируйте или раскомментируйте язык, чтобы отключить или включить его. Его необходимо скомпилировать и обновить, чтобы изменения вступили в силу, поэтому перезапустите терминал с помощью <code>npm run dev</code>, и вы должны увидеть добавленные/удаленные языки в выводе.</p><h2 id="пример-переопределения-языка" tabindex="-1">Пример переопределения языка <a class="header-anchor" href="#пример-переопределения-языка" aria-label="Permalink to &quot;Пример переопределения языка&quot;">​</a></h2><p>По умолчанию все языковые файлы будут иметь одинаковые KV. Однако вы можете переопределить поле определенного языка, чтобы компилятор использовал другую строку для этого языка. Это делается с помощью свойства <code>language_override</code>, которое доступно всем объектам всплывающей подсказки. Давайте приведем пример использования переопределения языка:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts</span></span>
<span class="line"><span>StandardTooltips.push({</span></span>
<span class="line"><span>  classname: &#39;standard_tooltip_example&#39;,</span></span>
<span class="line"><span>  name: &#39;Tooltip Example&#39;,</span></span>
<span class="line"><span>  language_overrides: [</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>      language: Language.Russian,</span></span>
<span class="line"><span>      name_override: &#39;Пример всплывающей подсказки&#39;,</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>  ],</span></span>
<span class="line"><span>});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>Как показано в примере, мы переопределяем поле <code>name</code> имени класса <code>standard_tooltip_example</code> другим текстом. Это сделано специально для русского языка с помощью объекта переопределения языка для Стандартной подсказки. Дополнительные объекты можно добавить для каждого языка, для которого мы хотим иметь отдельный текст. В результате получаются следующие KV:</p><p>::: кодовая группа</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[English]</span></span>
<span class="line"><span>&quot;standard_tooltip_example&quot;    &quot;Tooltip Example&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Russian]</span></span>
<span class="line"><span>&quot;standard_tooltip_example&quot;    &quot;Пример всплывающей подсказки&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Standard Chinese]</span></span>
<span class="line"><span>&quot;standard_tooltip_example&quot;    &quot;Tooltip Example&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>:::</p><p>If you checked the Standard Chinese KV, you probably saw that it retains its English language. Because it was not overridden, it still used the &quot;main&quot; value provided by the <code>name</code> property of the Standard Tooltip object.</p><h2 id="splitting-files-and-folders" tabindex="-1">Splitting Files and Folders <a class="header-anchor" href="#splitting-files-and-folders" aria-label="Permalink to &quot;Splitting Files and Folders&quot;">​</a></h2><p>One of the biggest annoyances with the localization files is the inability to split them to different files without using a script. The tooltip generator allows you to split your tooltips to as many files and folders as you need, as long as those files and folders are created inside the <code>resource/localization</code> directory.</p><p>For a tooltip file to also properly be watched and processed, it must have the following code:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ts</span></span>
<span class="line"><span>import {</span></span>
<span class="line"><span>  AbilityLocalization,</span></span>
<span class="line"><span>  Language,</span></span>
<span class="line"><span>  LocalizationData,</span></span>
<span class="line"><span>  ModifierLocalization,</span></span>
<span class="line"><span>  StandardLocalization,</span></span>
<span class="line"><span>} from &#39;~generator/localizationInterfaces&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export function GenerateLocalizationData(): LocalizationData {</span></span>
<span class="line"><span>  // This section can be safely ignored, as it is only logic.</span></span>
<span class="line"><span>  //#region Localization logic</span></span>
<span class="line"><span>  // Arrays</span></span>
<span class="line"><span>  const Abilities: Array&lt;AbilityLocalization&gt; = new Array&lt;AbilityLocalization&gt;();</span></span>
<span class="line"><span>  const Modifiers: Array&lt;ModifierLocalization&gt; = new Array&lt;ModifierLocalization&gt;();</span></span>
<span class="line"><span>  const StandardTooltips: Array&lt;StandardLocalization&gt; = new Array&lt;StandardLocalization&gt;();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // Create object of arrays</span></span>
<span class="line"><span>  const localization_info: LocalizationData = {</span></span>
<span class="line"><span>    AbilityArray: Abilities,</span></span>
<span class="line"><span>    ModifierArray: Modifiers,</span></span>
<span class="line"><span>    StandardArray: StandardTooltips,</span></span>
<span class="line"><span>  };</span></span>
<span class="line"><span>  //#endregion</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // Enter localization data below!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // Return data to compiler</span></span>
<span class="line"><span>  return localization_info;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br></div></div><p>Не имеет значения, какое у него имя, главное, чтобы оно имело расширение <code>.ts</code>. Подсказки располагаются между комментарием <code>Enter localization data below!</code> и комментарием <code>Return data to compiler</code>.</p><p>:::информация Я рекомендую сделать из него фрагмент, чтобы можно было легко создавать такую подпись для каждого создаваемого файла. Вы можете скопировать его из файла примера <code>localizationData.ts</code> для каждого файла, который вам нужен. :::</p><h2 id="dota-reimagined-в-качестве-примеров-таланты-обновленные-эффекты" tabindex="-1">Dota Reimagined в качестве примеров (таланты, обновленные эффекты) <a class="header-anchor" href="#dota-reimagined-в-качестве-примеров-таланты-обновленные-эффекты" aria-label="Permalink to &quot;Dota Reimagined в качестве примеров (таланты, обновленные эффекты)&quot;">​</a></h2><p>Вы можете проверить <a href="https://github.com/Shushishtok/dota-reimagined/tree/master/game/resource/localization" target="_blank" rel="noreferrer">Dota Reimagined&#39;s github</a>, для которого я изначально разработал этот проект, чтобы увидеть, как он выглядит с точки зрения папок и файлов. У каждого героя есть свой файл в папке <code>heroes</code>, а у каждого предмета — свой файл в папке <code>items</code>. В папке <code>generic</code> есть файлы вроде <code>addon_game_mode</code>. Кроме того, в файлах героев используются переосмысленные эффекты и таланты, которые также преобразуются в уникальные KV, которые моя игра специально разработала для поиска в панораме. Вы можете проверить, как именно это работает, и внести свои собственные изменения в компилятор для поддержки ваших уникальных KV.</p>`,111)])])}const h=a(l,[["render",o]]);export{m as __pageData,h as default};
